import { useMemo, useState } from 'react';
import { JxChip, JxProgressCircle, JxBadge, JxPagination, JxEmptyState, JxButton } from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  quota: number;
  status: ProjectStatus;
}

const projects: Project[] = [
  { id: 'p1', name: 'Атлас', quota: 42, status: 'active' },
  { id: 'p2', name: 'Компас', quota: 78, status: 'active' },
  { id: 'p3', name: 'Маяк', quota: 15, status: 'paused' },
  { id: 'p4', name: 'Орбита', quota: 96, status: 'over' },
  { id: 'p5', name: 'Северный ветер', quota: 55, status: 'active' },
  { id: 'p6', name: 'Гранит', quota: 30, status: 'paused' },
  { id: 'p7', name: 'Резонанс', quota: 88, status: 'over' },
  { id: 'p8', name: 'Прибой', quota: 12, status: 'active' },
  { id: 'p9', name: 'Тропа', quota: 64, status: 'paused' },
  { id: 'p10', name: 'Вектор', quota: 100, status: 'over' },
  { id: 'p11', name: 'Полюс', quota: 47, status: 'active' },
];

const statusMeta: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'danger' }> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'warning' },
  over: { label: 'Превышена', tone: 'danger' },
};

const statusFilters: ProjectStatus[] = ['active', 'paused', 'over'];
const pageSize = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(statusFilters);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(statusFilters);
    setPage(1);
  };

  const filtered = useMemo(
    () => projects.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses]
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
  const visible = filtered.slice((page - 1) * pageSize, page * pageSize);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r)' }}>
      <div style={{ display: 'flex', gap: 'var(--jx-r-xs)', flexWrap: 'wrap' }}>
        {statusFilters.map((status) => (
          <JxChip
            key={status}
            active={activeStatuses.includes(status)}
            removable={activeStatuses.includes(status)}
            onRemove={() => toggleStatus(status)}
            onClick={() => !activeStatuses.includes(status) && toggleStatus(status)}
          >
            {statusMeta[status].label}
          </JxChip>
        ))}
      </div>

      {filtered.length === 0 ? (
        <JxEmptyState
          title="Нет проектов с такими фильтрами"
          message="Попробуйте выбрать другой статус или сбросьте фильтры."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
            {visible.map((project) => (
              <div
                key={project.id}
                className="jx-row"
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 'var(--jx-r)',
                  padding: 'var(--jx-r-xs)',
                  borderRadius: 'var(--jx-r)',
                  background: 'var(--jx-surface)',
                  border: '1px solid var(--jx-border)',
                }}
              >
                <span style={{ color: 'var(--jx-text)', fontFamily: 'var(--jx-font-sans)' }}>{project.name}</span>
                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--jx-r)' }}>
                  <JxProgressCircle value={project.quota} showValue />
                  <JxBadge tone={statusMeta[project.status].tone} dot>
                    {statusMeta[project.status].label}
                  </JxBadge>
                </div>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={page} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

